window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-23201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κητεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2416 na letra κ · nº geral 23201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pesca de grandes peixes do mar, partic. do atum 2 lugar de pesca; pesqueiro. 〈κῆτος〉</p></section></article>\n<article id=\"entry-dgp-23202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κητοθηρεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2417 na letra κ · nº geral 23202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">loja de apetrechos para a pesca de peixes grandes. 〈κῆτος, θήρα〉</p></section></article>\n<article id=\"entry-dgp-23203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κητόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2418 na letra κ · nº geral 23203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">engordar como uma baleia. 〈κῆτος〉</p></section></article>\n<article id=\"entry-dgp-23204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κῆτος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2419 na letra κ · nº geral 23204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 monstro marinho 2 peixe marinho de grandes dimensões 3 Astron. Baleia, constelação.</p></section></article>\n<article id=\"entry-dgp-23205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κητώεις, ώεσσα, ῶεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2420 na letra κ · nº geral 23205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de cavidades profundas, epít. da Lacedemônia 2 cavernoso, epít. do cavalo de Tróia.</p></section></article>\n<article id=\"entry-dgp-23206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἦφ’</h1><div class=\"entry-meta\"><span>DGP · ordem 2421 na letra κ · nº geral 23206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase dór. de καὶ εἶπ(ε), antes de vogal aspirada.</p></section></article>\n<article id=\"entry-dgp-23207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κηφεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2422 na letra κ · nº geral 23207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cefeu, rei da Etiópia, pai de Andrômeda.</p></section></article>\n<article id=\"entry-dgp-23208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κηφήν, ῆνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2423 na letra κ · nº geral 23208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abelha macho; zangão 2 que explora o trabalho alheio; plagiador 3 pessoa decrépita, inútil.</p></section></article>\n<article id=\"entry-dgp-23209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κηφισίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2424 na letra κ · nº geral 23209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. Καφίσις (fem.) que acolhe o Céfiso: Κηφ. λίμνη hom. lago onde deságua o Céfiso, i.e., o Copais. 〈Κήφισος〉</p></section></article>\n<article id=\"entry-dgp-23210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κήφισος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2425 na letra κ · nº geral 23210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Κηφισός, οῦ (ὁ) Céfiso, n. de rio da Fócida e da Ática.</p></section></article>\n<article id=\"entry-dgp-23211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κηώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2426 na letra κ · nº geral 23211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perfumado. 〈καίω〉</p></section></article>\n<article id=\"entry-dgp-23212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κηώεις, ώεσσα, ῶεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2427 na letra κ · nº geral 23212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κηώδης.</p></section></article>\n<article id=\"entry-dgp-23213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιβδηλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2428 na letra κ · nº geral 23213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falsificar (moeda); adulterar (mercadoria) 2 agir de má fé; enganar. 〈κίβδηλος〉</p></section></article>\n<article id=\"entry-dgp-23214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίβδηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2429 na letra κ · nº geral 23214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de má qualidade; falsificado; adulterado 2 falso; fraudulento; desonesto; enganador (pessoa; caráter, desígnio) 3 ambíguo; incerto (oráculo) 4 bíbl. misto; de fibras diversas (tecido).</p></section></article>\n<article id=\"entry-dgp-23215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιβώριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2430 na letra κ · nº geral 23215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cibório, fruto da fava-do-egito ou colocásia, planta 2 cibório, copo feito com a vagem dessa planta ou que tem a sua forma 3 Arquit. cibório, em Roma.</p></section></article>\n<article id=\"entry-dgp-23216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιβώτιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2431 na letra κ · nº geral 23216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dimin. de κιβωτός.</p></section></article>\n<article id=\"entry-dgp-23217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιβωτοποιός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2432 na letra κ · nº geral 23217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fabricante de caixas e cofres. 〈κιβω­τός, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-23218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιβωτός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2433 na letra κ · nº geral 23218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caixa; cofre 2 bíbl. arca de Noé, da Aliança.</p></section></article>\n<article id=\"entry-dgp-23219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιγκλίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2434 na letra κ · nº geral 23219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 grade; barreira 2 pl., em Atenas, porta de dois batentes de acesso dos juízes ao tribunal ou ao conselho 3 recinto de tribunal; corte 4 penalidade; pena 5 barreira, grade de metal: ἐντὸς τῆς κιγκλίδος διατρίβειν luc. viver no interior de grades, i.e., viver enjaulado. 〈κλείω1〉</p></section></article>\n<article id=\"entry-dgp-23220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίγκλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2435 na letra κ · nº geral 23220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">melro d’água, ave que não constrói ninho: expr. κίγκλου πτωχότερος men. mais pobre que um melro d’água.</p></section></article>\n<article id=\"entry-dgp-23221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιγχάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2436 na letra κ · nº geral 23221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) = κιχάνω.</p></section></article>\n<article id=\"entry-dgp-23222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίδαρις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2437 na letra κ · nº geral 23222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 turbante, diadema de reis asiáticos 2 espécie de dança dos arcádios.</p></section></article>\n<article id=\"entry-dgp-23223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίδναμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2438 na letra κ · nº geral 23223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ἐκιδνάμην) espalhar-se; difundir-se; estender-se: ὑπεὶρ ἅλα κίδναται ἠώς hom. aurora se espalha sobre o mar, ὀδμὰ κατὰ χῶρον κίδναται pínd. um olor se espalha pela região, ὕπνος ἐπ’ ὄσσοις κίδναται eur. o sono se estende sobre os olhos.</p></section></article>\n<article id=\"entry-dgp-23224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιθαιρών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2439 na letra κ · nº geral 23224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Citerão, monte entre a Ática e a Beócia.</p></section></article>\n<article id=\"entry-dgp-23225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθάρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2440 na letra κ · nº geral 23225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cítara, espécie de alaúde ou de lira 2 cítara, planta 3 Anat. tórax 4 pl. costelas (de cavalo).</p></section></article>\n<article id=\"entry-dgp-23226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαραοιδός,</h1><div class=\"entry-meta\"><span>DGP · ordem 2441 na letra κ · nº geral 23226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. κιθαρῳδός, οῦ (ὁ) 1 pessoa que canta ao som da cítara; citarista 2 espécie de peixe. 〈κιθάρα, ἀοιδός〉</p></section></article>\n<article id=\"entry-dgp-23227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθάρη</h1><div class=\"entry-meta\"><span>DGP · ordem 2442 na letra κ · nº geral 23227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = κιθάρα.</p></section></article>\n<article id=\"entry-dgp-23228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2443 na letra κ · nº geral 23228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tocar cítara ou alaúde: κιθαρίζειν οὐκ ἐπίσ­ταμαι ar. não sei tocar cítara, ref. a pessoa sem educação 2 executar em instrumento de cordas: κιθ. τι φόρμιγγι hom. tocar algo na lira ♦ pas. τὸ κιθαριζόμενον 3 música para cítara. 〈κιθάρα〉</p></section></article>\n<article id=\"entry-dgp-23229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίθαρις, ιος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2444 na letra κ · nº geral 23229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cítara 2 arte de tocar cítara. 〈κιθάρα〉</p></section></article>\n<article id=\"entry-dgp-23230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθάρισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2445 na letra κ · nº geral 23230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de tocar cítara. 〈κιθαρίζω〉</p></section></article>\n<article id=\"entry-dgp-23231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιταριστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2446 na letra κ · nº geral 23231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">citarista. 〈κιθάρα〉</p></section></article>\n<article id=\"entry-dgp-23232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαριστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2447 na letra κ · nº geral 23232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 relativo à execução da cítara 2 hábil em tocar cítara ♦ ἡ κιθαριστική 3 arte de tocar cítara. 〈κιθαρίζω〉</p></section></article>\n<article id=\"entry-dgp-23233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαριστικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 2448 na letra κ · nº geral 23233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com hábil execução da cítara.</p></section></article>\n<article id=\"entry-dgp-23234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαρῳδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2449 na letra κ · nº geral 23234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cantar com acompanhamento de cítara. 〈κιθαρῳδός〉</p></section></article>\n<article id=\"entry-dgp-23235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαρῳδικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2450 na letra κ · nº geral 23235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne ao canto acompanhado de cítara ♦ ἡ κιθαρῳδική 2 arte de cantar com acompanhamento da cítara. 〈κιθαρῳδός〉</p></section></article>\n<article id=\"entry-dgp-23236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθαρῳδός</h1><div class=\"entry-meta\"><span>DGP · ordem 2451 na letra κ · nº geral 23236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de κιθαραοιδός.</p></section></article>\n<article id=\"entry-dgp-23237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιθών</h1><div class=\"entry-meta\"><span>DGP · ordem 2452 na letra κ · nº geral 23237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = χιτών.</p></section></article>\n<article id=\"entry-dgp-23238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίκι, κίκεως (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2453 na letra κ · nº geral 23238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rícino, arbusto.</p></section></article>\n<article id=\"entry-dgp-23239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κικλήσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 2454 na letra κ · nº geral 23239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ἐκίκλησκον, ép. κίκλησκον) poét. 1 chamar; convocar: εἰς ἀγορὴν κικλήσκειν ἄνδρα ἕκαστον hom. convocar para a assembléia cada guerreiro 2 convidar 3 invocar; interpelar 4 chamar pelo nome 5 atribuir um nome; denominar: τὸν ἐπίκλησιν κορυνήτην ἄνδρες κίκλησκον hom. a ele os homens chamavam porta-clava ♦ pas. 6 ser denominado: νῆσος Συρίη κικλήσκεται hom. esta ilha é chamada de Siros 7 receber o nome de alguém, gen.: πατρὸς δὲ Στρύμονος κικλήσκεται eur. tem o nome do pai, Estrimão.</p></section></article>\n<article id=\"entry-dgp-23240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κῖκυς, υος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2455 na letra κ · nº geral 23240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">força; energia; vigor.</p></section></article>\n<article id=\"entry-dgp-23241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιλικία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2456 na letra κ · nº geral 23241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cilícia, região da Ásia Menor.</p></section></article>\n<article id=\"entry-dgp-23242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιλίκιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2457 na letra κ · nº geral 23242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Cilícia: ἄρτος Κιλ. pão da Cilícia, i.e, pão rústico. 〈Κίλιξ〉</p></section></article>\n<article id=\"entry-dgp-23243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κίλιξ, ικος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2458 na letra κ · nº geral 23243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Cílix, epônimo da Cilícia ♦ οἱ Κίλικες 2 os Cilícios ♦ adj. masc. e fem. 3 habitante ou originário da Cilícia 4 da Cilícia; cilício (coisa).</p></section></article>\n<article id=\"entry-dgp-23244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κίλισσα, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 2459 na letra κ · nº geral 23244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) da Cilícia. 〈Κίλιξ〉</p></section></article>\n<article id=\"entry-dgp-23245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιλλικύριοι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2460 na letra κ · nº geral 23245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">classe de escravos, em Siracusa.</p></section></article>\n<article id=\"entry-dgp-23246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιλλύριοι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2461 na letra κ · nº geral 23246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cilírios, povo da Sicília.</p></section></article>\n<article id=\"entry-dgp-23247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιμμερικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2462 na letra κ · nº geral 23247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dos cimérios do Quersoneso Táurico.</p></section></article>\n<article id=\"entry-dgp-23248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιμμέριος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 2463 na letra κ · nº geral 23248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, jôn., η, ον 1 dos cimérios; cimerianos: τὰ Κιμμέρια τείχεα her. os Muros Cimerianos, cidade do Quersoneso Táurico ♦ οἱ Κιμμέριοι 2 os cimérios, povo das margens do Oceano 3 os cimérios, povo do Quersoneso Táurico ♦ ἡ Κιμμερίη 4 a Ciméria, cidade dos cimérios.</p></section></article>\n<article id=\"entry-dgp-23249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιμωλία, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 2464 na letra κ · nº geral 23249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Cimolo, uma da Cíclades: Κίμωλος γῆ ar. terra branca ou vermelha de Cimolo, tipo de giz que contém soda, que as lavadeiras de Atenas misturavam com cinza.</p></section></article>\n<article id=\"entry-dgp-23250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κίμων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2465 na letra κ · nº geral 23250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Címon, n. do pai e do filho de Milcíades.</p></section></article>\n<article id=\"entry-dgp-23251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κιμώνειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2466 na letra κ · nº geral 23251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Címon ♦ τὰ Κιμώνεια 2 os restos do palácio de Címon, perto de Atenas.</p></section></article>\n<article id=\"entry-dgp-23252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινάβρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2467 na letra κ · nº geral 23252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fedor de bode; cheiro pestilento (de axila, de barba suja) 2 barba de bode.</p></section></article>\n<article id=\"entry-dgp-23253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιναβράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2468 na letra κ · nº geral 23253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feder como bode. 〈κινάβρα〉</p></section></article>\n<article id=\"entry-dgp-23254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίναδος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2469 na letra κ · nº geral 23254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 raposa, para os sicilianos 2 homem astuto, enganador 3 fera; monstro.</p></section></article>\n<article id=\"entry-dgp-23255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινάθισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2470 na letra κ · nº geral 23255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barulho de um objeto em movimento; agitação. 〈κινέω〉</p></section></article>\n<article id=\"entry-dgp-23256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιναιδεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2471 na letra κ · nº geral 23256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perversão sexual; homossexualismo. 〈κίναιδος〉</p></section></article>\n<article id=\"entry-dgp-23257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίναιδος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2472 na letra κ · nº geral 23257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 devasso; homossexual 2 pl. versos fesceninos 3 espécie de peixe.</p></section></article>\n<article id=\"entry-dgp-23258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κινδυεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 2473 na letra κ · nº geral 23258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de Cindieu, vilarejo da Cária.</p></section></article>\n<article id=\"entry-dgp-23259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινδύνευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2474 na letra κ · nº geral 23259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">empresa arriscada; rasgo de bravura ou de risco. 〈κινδυνεύω〉</p></section></article>\n<article id=\"entry-dgp-23260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινδυνευτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 2475 na letra κ · nº geral 23260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de κινδυνεύω.</p></section></article>\n<article id=\"entry-dgp-23261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινδυνευτής, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 2476 na letra κ · nº geral 23261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que afronta o perigo; intrépido; audaz. 〈κινδυνεύω〉</p></section></article>\n<article id=\"entry-dgp-23262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινδυνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2477 na letra κ · nº geral 23262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κινδυνεύσω, aor. ἐκινδύνευσα, perf. κεκιν­δύνευκα) ativa 1 estar em perigo; correr perigo; correr risco em relação a, dat. ou ἐν e dat., περί e gen. ou περί e dat. ou ὑπέρ e gen. 2 correr risco de; arriscar-se a, inf. 3 afrontar um perigo de guerra; combater 4 correr perigo de condenação 5 haver chance de; haver probabilidade de; ter oportunidade de, constr. pes. com inf.; impes. κινδυνεύει é bem possível; pode ser, como resposta afirmativa passiva 6 (coisa) ser ameaçado por perigo 1 τοῦτο τὸ κινδύνευμα κινδ. plat. correr este perigo, κινδ. τῷ σώματι ou τῇ ψυχῇ her. ou τῷ βίῳ pol., περὶ τοῦ βίου ar., περὶ τοῦ σώματος and., περὶ τῆς ψυχῆς ant. correr perigo de vida, τίσιν οὖν ὑμεῖς κινδυνεύσαιτ’ ἄν dem. que riscos vós poderíeis correr?, κινδ. περὶ αὑτῷ ant. estar em perigo por si mesmo, κινδ. περὶ τοῖς φιλτάτοις plat. correr perigo pelo que se tem de mais caro, ἐν τοῖς σώμασι τοῖς ἑαυτῶν κινδ. lís. arriscar a própria vida, κινδυνεύοντος τοῦ χωρίου tuc. estando a região em perigo, ὁ κινδυνεύοντος τόπος pol. o posto em perigo 2 κινδ. ἀποθανεῖν plut., ἀπολέσθαι her., arriscar-se a morrer, a perecer, ἡ πόλις ἐκινδύνευσε πᾶσα διαφθαρῆναι tuc. a cidade inteira correu o risco de ser destruída 3 ἐτοίμως κινδ. πρὸς τοὺς πολεμίους xen. estar pronto para enfrentar os inimigos 4 κινδ. ψευδομαρτυρίαν dem. correr perigo de condenação por falso testemunho, κινδ. περὶ τῆς μεγίστης ζημίας lís. correr perigo de pena máxima 5 κινδυνεύουσι γόητες εἶναι her. há possibilidade de que sejam impostores, κινδυνεύει ἀναμφιλογώτατον ἀγαθὸν εἶναι τὸ εὐδαιμονεῖν xen. pode bem se que a felicidade seja o bem menos contestável, κινδυνεύεις ἀληθῆ λέγειν plat. pode ser que estejas dizendo a verdade 6 τὰ μέγιστα κινδυνεύεται τῇ πόλει dem. o Estado corre os maiores perigos, τὰ κινδυνευθέντα lís., τὰ κεκινδυνευμένα artt. os perigos enfrentados. 〈κίνδυνος〉</p></section></article>\n<article id=\"entry-dgp-23263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίνδυνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2478 na letra κ · nº geral 23263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perigo: κίνδυνον ὑπομεῖναι xen. resistir de pé firme a um perigo, κινδύνους κινδυνεύειν ant., αἵρεσθαι eur., ξυναίρεσθαι ou ἐγχειρίζεσθαι tuc., ἀναλαβέσθαι her., ὑποδύεσθαι xen., ποιεῖσθαι isócr. enfrentar um perigo, correr perigo, ἐς κίνδυνον ἔρχεσθαι xen., ἐμβαίνειν xen. e κινδύνῳ περιπίπτειν teócr. expor-se a um perigo, ἐν κινδύνοις εἶναι dem. estar em perigo, τινὰ εἰς κίνδυνον καθιστάναι tuc., κινδύνῳ βάλλειν τινά ésql., φέρειν ou ἐπιφέρειν τινὶ κινδύνους ésqn. pôr alguém em perigo, κίνδυνος καταλαμβάνει τινά dem., κίνδυνος γίγνεταί τινι xen. constitui perigo para alguém, κίνδυνος ἔχειν ou εἶναι com or. inf. haver perigo de, κίνδυνον ἀλύσκω batr. tendo evitado o perigo, κίνδυνον διαλύειν dem. dissipar um perigo 2 guerra; combate 3 empresa arriscada.</p></section></article>\n<article id=\"entry-dgp-23264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινδυνώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2479 na letra κ · nº geral 23264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perigoso; arriscado. 〈κίνδυνος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-23265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2480 na letra κ · nº geral 23265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κινήσω, aor. ἐκίνησα, perf. κεκίνηκα; fut. κιν­ήσομαι e κινηθήσομαι, aor. ἐκινήθην com sent. méd.) ativa 1 mover; pôr em movimento; remexer; agitar 2 mudar de lugar; deslocar; remover; mexer em, ac. 3 mover violentamente; sacudir; agitar; perturbar 4 pressionar; incitar; excitar; estimular algo ou alguém, ac. 5 subverter; alterar; mudar médio-passiva 6 (assembléias, tropas) mover-se; pôr-se em movimento 7 ir; andar 8 movimentar-se; mover-se na dança 9 (terra) sofrer abalo sísmico; tremer 10 ser perito em, περί e ac. 1 κιν. πόδα eur. mover o pé, κιν. τὰς χεῖρας καὶ τὴν κεφα­λήν plat. movimentar as mãos e a cabeça, κιν. ὅπλα tuc. pôr em movimento, tomar as armas, prov. κιν. πᾶν χρῆμα her. ou κιν. πάντα κάλων ou κιν. πάντα λόγον plat. mover todos os meios, todos os cabos, todos os argumentos, i.e., empregar todos os meios 2 μὴ κινέειν τὸν ἀνδριάντα her. não remover a estátua, κιν. γῆς ὅρια plat. mudar de lugar uma fronteira, κιν. τὶ τῶν ἀκι­νήτων her. mexer em algo intocável, κιν. τὸ στρατοπέδον ou τὸ στρατόν xen. levantar acampamento, τὰ χρήματα ἐς ἄλλοτι tuc. empregar o dinheiro em outra coisa, κινεῖν τῶν χρημάτων tuc. levar parte do dinheiro 3 κιν. σφῆκας hom. alvoroçar as vespas, καὶ εἶπον κινή­σας αὐτὸν· Σωκράτες, καθεύδεις; plat. e depois de sacudi-lo, eu disse: “Sócrates, estás dormindo?”, ἐξ ὕπνου κινεῖν δέμας eur. do sono remove o corpo, φόβος κινεῖ ésql. o medo comove 4 ἡλίου σέλας κινεῖ φθέγματ’ ὀρνίθων sóf. a luz do sol estimula o canto dos pássaros, κιν. ἀγρίαν ὀδύνην sóf. provocar sofrimento atroz, κινῶ σε πρὸς τὴν φιλοσοφίαν artt. incito-te à filosofia; Medic. κιν. οὔρησιν diosc. estimular a urina 5 κιν. νόμαια πάτρια her. subverter as leis ancestrais, κιν. τὰ καθεστῶτα isócr. subverter as normas vigentes 6 προεῖπεν ὡς μηδεὶς κινήσοιτο ἐκ τῆς τάξεως xen. ordenou que ninguém se movesse para fora de sua fileira 7 κινοῦνται πρὸς ἄστυ sóf. caminham na direção da cidade 8 κινεῖσθαι τῷ σώματι τὰ τοιαῦτα plat. fazer tais movimentos com o corpo 9 ∆ῆλος ἐκινήθη her. Delos sofreu abalo sísmico 10 περὶ πᾶσαν τὴν μαγγανείαν κεκινημένοι plat. peritos em todo tipo de magia.</p></section></article>\n<article id=\"entry-dgp-23266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίνημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2481 na letra κ · nº geral 23266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 movimento 2 movimento de dança, de pantomima 3 movimento da alma; comoção; emoção 4 vicissitudes da sorte 5 agitação; perturbação; sublevação política 6 Gram. flexão 7 Medic. luxação ou deslocamento. 〈κινέω〉</p></section></article>\n<article id=\"entry-dgp-23267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίνησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2482 na letra κ · nº geral 23267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de mover ou de mover-se; movimento 2 movimento de dança, de exército 3 movimento da alma; comoção 4 agitação; perturbação; sublevação 5 mudança; revolução 6 Gram. flexão. 〈κινέω〉</p></section></article>\n<article id=\"entry-dgp-23268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινητέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2483 na letra κ · nº geral 23268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de κινέω.</p></section></article>\n<article id=\"entry-dgp-23269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινητήριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2484 na letra κ · nº geral 23269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que põe em movimento; que agita. 〈κινέω〉</p></section></article>\n<article id=\"entry-dgp-23270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2485 na letra κ · nº geral 23270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que põe em movimento; que move; que agita, gen. 2 que estimula; que excita: κιν. πρὸς ἀρε­τήν plut. instigar à virtude 3 que causa agitação; agitador político 4 que se move; móvel. 〈κινέω〉</p></section></article>\n<article id=\"entry-dgp-23271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινητός, ή</h1><div class=\"entry-meta\"><span>DGP · ordem 2486 na letra κ · nº geral 23271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ός, όν 1 que se pode mover; móvel 2 que pode ser mudado; mutável ♦ τὸ κινητόν 3 a mobilidade. 〈κινέω〉</p></section></article>\n<article id=\"entry-dgp-23272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιννάβαρι, εως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2487 na letra κ · nº geral 23272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cinabre, sulfeto de mercúrio, de cor vermelha, empregado como tintura 2 garança; granza; ruiva, planta.</p></section></article>\n<article id=\"entry-dgp-23273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινναμώμινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2488 na letra κ · nº geral 23273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cinamomo ou de caneleira. 〈κιννά­μωμον〉</p></section></article>\n<article id=\"entry-dgp-23274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιννάμωμον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2489 na letra κ · nº geral 23274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cinamomo ou canela, árvore ♦ adj. 2 que amontoa ramos de canela para fazer o ninho (pássaro).</p></section></article>\n<article id=\"entry-dgp-23275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίνυγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2490 na letra κ · nº geral 23275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">corpo suspenso e em movimento; joguete no ar. 〈κινύσσομαι〉</p></section></article>\n<article id=\"entry-dgp-23276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίνυμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2491 na letra κ · nº geral 23276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ἐκινύμην) 1 mover-se numa dança 2 pôr-se em movimento; partir: κίν. ἐς πόλεμον hom. partir para a guerra ♦ pas. 3 ser sacudido, agitado.</p></section></article>\n<article id=\"entry-dgp-23277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινύρομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2492 na letra κ · nº geral 23277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., impf. e aor.) poét. 1 intr. lamentar-se; gemer 2 deplorar 3 fazer ressoar: χαλινοὶ κινύρονται φόνον ésql. com seu ranger os freios choram a mortandade. 〈κινυρός〉</p></section></article>\n<article id=\"entry-dgp-23278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινυρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2493 na letra κ · nº geral 23278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">queixoso; lamentável.</p></section></article>\n<article id=\"entry-dgp-23279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κινύσσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2494 na letra κ · nº geral 23279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. ἐκινυσσόμην) pas. ser agitado, sacudido. 〈κινέω〉</p></section></article>\n<article id=\"entry-dgp-23280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιόκρανον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2495 na letra κ · nº geral 23280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κιονόκρανον.</p></section></article>\n<article id=\"entry-dgp-23281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιονόκρανον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2496 na letra κ · nº geral 23281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cabeça de coluna; capitel. 〈κίων, κρανίον〉</p></section></article>\n<article id=\"entry-dgp-23282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κίος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2497 na letra κ · nº geral 23282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Quios, cidade da Bitínia.</p></section></article>\n<article id=\"entry-dgp-23283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίρκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2498 na letra κ · nº geral 23283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ave de rapina. 〈κίρκος〉</p></section></article>\n<article id=\"entry-dgp-23284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κίρκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2499 na letra κ · nº geral 23284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Circe, maga, filha do deus Hélio e tia de Medéia.</p></section></article>\n<article id=\"entry-dgp-23285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιρκήλατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2500 na letra κ · nº geral 23285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perseguido por ave de rapina. 〈κίρκη, ἐλαύνω〉</p></section></article>\n<article id=\"entry-dgp-23286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίρκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2501 na letra κ · nº geral 23286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espécie de falcão; gavião 2 espécie de lobo 3 anel; círculo 4 circo, em Roma.</p></section></article>\n<article id=\"entry-dgp-23287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιρκόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2502 na letra κ · nº geral 23287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prender em um anel.</p></section></article>\n<article id=\"entry-dgp-23288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίρνας</h1><div class=\"entry-meta\"><span>DGP · ordem 2503 na letra κ · nº geral 23288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. at. de κίρνημι.</p></section></article>\n<article id=\"entry-dgp-23289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κιρνάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2504 na letra κ · nº geral 23289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) 1 misturar; mesclar uma coisa, ac., a outra, dat.: κ. οἶνον hom. misturar o vinho (com a água), κ. κόμπον ἀοιδᾷ pínd. mesclar ao canto o elogio 2 preparar uma mistura de uma coisa, dat., com outra, dat.: κ. θείῳ καὶ ἀσφάλτῳ herod. fazer uma mistura de enxôfre e asfalto 3 preparar um recipiente, ac., com mistura de, gen.: κ. κρατῆρα οἴνου her. preparar uma cratera de vinho 4 temperar; suavizar ♦ méd. pas. 5 misturar-se; mesclar-se 6 Gram. contrair-se; sofrer contração: κ. ἐς δίφθογγον a.d. contrair-se em ditongo.</p></section></article>\n<article id=\"entry-dgp-23290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίρνη</h1><div class=\"entry-meta\"><span>DGP · ordem 2505 na letra κ · nº geral 23290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. pres. impf. at. de κίρνημι.</p></section></article>\n<article id=\"entry-dgp-23291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίρνημι</h1><div class=\"entry-meta\"><span>DGP · ordem 2506 na letra κ · nº geral 23291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) = κιρνάω.</p></section></article>\n<article id=\"entry-dgp-23292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίσηρις</h1><div class=\"entry-meta\"><span>DGP · ordem 2507 na letra κ · nº geral 23292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e κίσσηρις, εως (ἡ) pedra-pomes.</p></section></article>\n<article id=\"entry-dgp-23293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κισηροειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2508 na letra κ · nº geral 23293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante à pedra-pomes. 〈κίσηρις, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-23294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κισηρώδης</h1><div class=\"entry-meta\"><span>DGP · ordem 2509 na letra κ · nº geral 23294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e κισσηρώδης, ης, ες = κισηροειδής.</p></section></article>\n<article id=\"entry-dgp-23295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίσθος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2510 na letra κ · nº geral 23295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cisto, arbusto.</p></section></article>\n<article id=\"entry-dgp-23296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίσσα,</h1><div class=\"entry-meta\"><span>DGP · ordem 2511 na letra κ · nº geral 23296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. κίττα, ης (ἡ) 1 pega, pássaro 2 desejo de mulher grávida.</p></section></article>\n<article id=\"entry-dgp-23297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κισσάω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2512 na letra κ · nº geral 23297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. κιττάω-ῶ 1 (mulher grávida) ter desejo de algo, gen. 2 desejar apaixonadamente, gen. ou inf. 3 ficar grávida; conceber.</p></section></article>\n<article id=\"entry-dgp-23298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κισσεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2513 na letra κ · nº geral 23298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cisseu, pai de Hécuba.</p></section></article>\n<article id=\"entry-dgp-23299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κισσηΐς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2514 na letra κ · nº geral 23299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 filha de Cisseu, Hécuba 2 a filha de Cisseu, Teano. 〈Κισσεύς〉</p></section></article>\n<article id=\"entry-dgp-23300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κίσσηλις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2515 na letra κ · nº geral 23300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κίσηρις.</p></section></article>\n";
